/* TriM3 · 头像迷你播放器（Meting API / 自定义歌单）
 *
 * 结构（首页个人信息卡）：
 *  - .tri-player-avatar  头像容器：未播放显示博主头像，hover 浮现播放键；
 *                          播放中 img 变为歌曲封面，头像框内显示 上曲/播放暂停/下曲
 *  - .player-side        名字右侧横排控制：音量/歌单/歌词
 *  - .player-progress    banner 底部分界处细进度条（可点击跳转）
 *  - .player-lyric-float 左下角无背景歌词浮层（有 LRC 时随播放时间同步，否则 2 行轮播）
 *
 * 数据源：Meting API（平台+资源ID 异步拉取 name/artist/url/pic/lrc）
 *         或自定义歌单（封面 | 标题 | 音频 | 歌手）。
 * 可视化：Web Audio AnalyserNode 频谱（需音频支持 CORS，失败自动降级 CSS 音柱动画）
 */
(function () {
  'use strict';

  /* Save old instance state before overwriting (Swup may re-execute this script) */
  // Global flag to prevent re-execution across Swup/PJAX navigation
  if (window._triPlayerLoaded && window.TriPlayer) { return; }
  window._triPlayerLoaded = true;

  var CFG = window.TRI3_PLAYER || { enabled: false, list: [], volume: '0.7' };
  if (!CFG.enabled) { return; }

  var idx = 0;
  var playing = false;

  var muted = false;
  var vol = parseFloat(CFG.volume);
  if (isNaN(vol) || vol < 0 || vol > 1) { vol = 0.7; }
  try { var mv = localStorage.getItem('tri3_player_vol'); if (mv !== null) { vol = parseFloat(mv); } } catch (e) {}
  var audio = null;
  var ctx = null;
  var analyser = null;
  var srcNode = null;
  var rafId = null;
  var lrcData = null; /* 当前歌曲 LRC：[{t, text}] */

  var q = function (s) { return document.querySelector(s); };

  function initAudio() {
    if (audio) { return; }
    audio = new Audio(); audio.crossOrigin = "anonymous";
    audio.preload = 'none';
    audio.volume = vol;
    audio.addEventListener('timeupdate', onTime);
    audio.addEventListener('loadedmetadata', onMeta);
    audio.addEventListener('ended', function () { next(); });
    audio.addEventListener('play', function () { playing = true; syncUI(); switchCover(); refreshDock(); });
    audio.addEventListener('pause', function () {
      playing = false;
      syncUI();
      refreshDock();
      /* 头像/名字的恢复由 restoreAll 在显式暂停/失败路径调用，避免切歌闪回 */
    });
    audio.addEventListener('error', function () {
      playing = false;
      syncUI();
      refreshDock();
      var prog = q('.player-progress');
      if (prog) { prog.classList.remove('is-on'); }
      toast('音频加载失败');
    });
    syncVolUI();
  }

  function toast(msg) { if (window.TriMsg) { window.TriMsg.show(msg); } }
  function current() { return CFG.list[idx] || { src: '', title: '', cover: '', artist: '' }; }

  function coverOf(item) { return (item && item.cover) || ''; }

  /* 播放时名字/简介切换为歌曲名/歌曲信息，停止恢复博主原名/简介 */
  var savedName = null;
  var savedBio = null;
  var savedAvatarSrc = null;
  function saveIdentity() {
    var n = q('.profile-name');
    var b = q('.profile-bio');
    if (savedName === null && n) { savedName = n.textContent; }
    if (savedBio === null && b) { savedBio = b.textContent; }
  }
  function saveAvatar() {
    if (savedAvatarSrc !== null) { return; }
    var img = q('.tri-player-avatar img');
    if (img) { savedAvatarSrc = img.src; }
  }
  function restoreAvatar() {
    var img = q('.tri-player-avatar img');
    if (img && savedAvatarSrc) { img.src = savedAvatarSrc; }
  }
  function applyIdentity() {
    var n = q('.profile-name');
    var b = q('.profile-bio');
    if (!n && !b) { return; }
    saveIdentity();
    if (playing) {
      var it = current();
      if (n) { n.textContent = it.title || savedName; }
      if (b) { b.textContent = it.artist || '正在播放'; }
    }
    /* 非播放状态的恢复由 restoreAll 显式驱动，避免切歌时闪回博主信息 */
  }
  function restoreAll() {
    restoreAvatar();
    var n = q('.profile-name');
    var b = q('.profile-bio');
    if (n && savedName !== null) { n.textContent = savedName; }
    if (b && savedBio !== null) { b.textContent = savedBio; }
  }

  /* 设置头像封面：加载失败自动回退博主头像，避免破图/占位灰图 */
  function applyAvatarSrc(src) {
    if (!src) { return; }
    /* HTTPS 站强制升级封面（网易云等封面源可能返回 http://，避免 Mixed Content 被浏览器拦截） */
    src = String(src).replace(/^http:\/\//i, 'https://');
    var img = q('.tri-player-avatar img');
    var dockImg = q('.dock-cover-img');
    if (img) {
      img.onerror = function () {
        img.onerror = null;
        if (savedAvatarSrc && img.src !== savedAvatarSrc) { img.src = savedAvatarSrc; }
      };
      img.src = src;
    }
    if (dockImg) { dockImg.src = src; }
  }
  function switchCover() {
    var avatarImg = q('.tri-player-avatar img');
    var item = current();
    var c = item.pic_api || item.pic || coverOf(item);
    if (avatarImg) {
      if (c) { applyAvatarSrc(c); }
      else if (savedAvatarSrc) { applyAvatarSrc(savedAvatarSrc); /* 无封面：恢复博主头像 */ }
    }
    var titleEl = q('.player-title');
    if (titleEl) { titleEl.textContent = item.title || ('曲目 ' + (idx + 1)); }
  }

  /* 播放第 i 首：先同步切封面，再懒加载音频地址/歌词 */
  function loadSong(i, onload) {
    var it = CFG.list[i];
    if (!it) { return; }
    /* 立即切到新歌封面（不等音频地址返回），避免切歌瞬间闪回博主头像 */
    var c = it.pic_api || it.pic || coverOf(it);
    if (c) { applyAvatarSrc(c); }
    var finish = function () {
      /* 歌词：lrc 可能是 URL 端点（懒加载）或已拉取的文本 */
      if (!it.lrcText && typeof it.lrc === 'string' && /^https?:\/\//.test(it.lrc)) {
        fetch(it.lrc).then(function (r) { return r.text(); }).then(function (t) {
          it.lrcText = t || '';
          if (idx === i && playing) {
            lrcData = parseLrc(it.lrcText);
            ensureLyricMode();
          }
        }).catch(function () { it.lrcText = ''; });
      } else {
        it.lrcText = it.lrcText || it.lrc || '';
      }
      if (idx === i) {
        lrcData = parseLrc(it.lrcText);
        ensureLyricMode();
      }
      onload && onload();
    };
    if (it.src) { finish(); }
    else if (it.url_id && CFG.meting && CFG.meting.api) {
      var api = String(CFG.meting.api).replace(/\/+$/, '');
      var srv = it.server || CFG.meting.server || 'netease';
      var url = api + '?server=' + encodeURIComponent(srv) +
                '&type=url&id=' + encodeURIComponent(it.url_id);
      fetch(url).then(function (r) { return r.json(); }).then(function (d) {
        it.src = d.url || '';
        finish();
      }).catch(function () { finish(); });
    } else {
      finish();
    }
  }

  function playAt(i) {
    var n = CFG.list.length;
    if (!n) { return; }
    idx = ((i % n) + n) % n;
    initAudio();
    loadSong(idx, function () {
      var it = current();
      if (!it.src) {
        toast('该曲目暂不可播放（可能为 VIP/需登录）');
        return;
      }
      audio.src = it.src;
      var prog = q('.player-progress');
      if (prog) { prog.classList.add('is-on'); }
      /* 提前启动可视化：点击手势内创建/恢复 AudioContext，缓冲期即有显示，不等待 play 成功 */
      startVis();
      audio.play().then(function () {
        playing = true;
        syncUI();
        switchCover();
      }).catch(function () {
        playing = false;
        syncUI();
        stopVis();
        toast('无法播放，请检查音频地址或跨域');
      });
    });
  }

  function togglePlay() {
    if (!audio) {
      playAt(idx);
      return;
    }
    if (audio.paused) {
      startVis();
      audio.play().then(function () { playing = true; syncUI(); }).catch(function () { toast('无法播放'); });
    } else {
      audio.pause();
      playing = false;
      syncUI();
      stopVis();
      restoreAll();
    }
  }
  function prev() { if (audio) { audio.pause(); } playAt(idx - 1); }
  function next() { if (audio) { audio.pause(); } playAt(idx + 1); }

  /* ---------- 进度条 ---------- */
  function onTime() {
    var bar = q('.player-progress-bar');
    var wrap = q('.player-progress');
    if (bar && wrap && audio && audio.duration && isFinite(audio.duration)) {
      var p = (audio.currentTime / audio.duration) * 100;
      bar.style.width = p + '%';
      if (wrap.hasAttribute('aria-valuenow')) { wrap.setAttribute('aria-valuenow', String(Math.round(p))); }
    }
    /* 歌词时间同步（滚动定位） */
    var box = q('.player-lyric-float');
    if (box && !box.hidden && lrcData && lrcData.length) {
      syncLrc();
    }
    syncDockProgress();
  }
  function onMeta() {
    var wrap = q('.player-progress');
    if (wrap) { wrap.classList.add('is-ready'); }
    onTime();
  }
  function seekTo(clientX) {
    var wrap = q('.player-progress');
    if (!wrap || !audio || !audio.duration) { return; }
    var r = wrap.getBoundingClientRect();
    var ratio = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    audio.currentTime = ratio * audio.duration;
    onTime();
  }

  /* ---------- 可视化（Web Audio 频谱，降级 CSS 音柱；启动即显示，平滑过渡） ---------- */
  var visSmooth = [];   /* 柱高平滑缓冲（lerp 跟随，避免跳动） */
  var visBoot = 0;      /* 启动缓冲期模拟律动相位 */

  function startVis() {
    var canvas = q('.player-vis');
    if (!canvas) { return; }
    try {
      if (!ctx) {
        var AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) { throw new Error('no ac'); }
        ctx = new AC();
        srcNode = ctx.createMediaElementSource(audio);
        analyser = ctx.createAnalyser();
        analyser.fftSize = 128;
        analyser.smoothingTimeConstant = 0.62;   /* 更快响应，视觉不迟滞 */
        srcNode.connect(analyser);
        analyser.connect(ctx.destination);
      }
      if (ctx.state === 'suspended') { ctx.resume(); }
    } catch (e) {
      /* 跨域或环境不支持：降级 CSS 动画 */
      canvas.classList.add('is-css');
      canvas.style.display = 'none';
    }
    canvas.classList.add('is-on');
    if (canvas.classList.contains('is-css')) {
      stopVis();
      canvas.style.display = 'none';
      var side = q('.player-side');
      if (side && !side.querySelector('.vis-css')) {
        var d = document.createElement('div');
        d.className = 'vis-css';
        for (var k = 0; k < 14; k++) { var s = document.createElement('span'); d.appendChild(s); }
        side.insertBefore(d, side.firstChild);
      }
      return;
    }
    visSmooth = [];
    visBoot = 0;
    var draw = function () {
      if (!analyser) { rafId = null; return; }
      rafId = requestAnimationFrame(draw);
      var active = playing && audio && !audio.paused;
      var data = new Uint8Array(analyser.frequencyBinCount);
      analyser.getByteFrequencyData(data);
      var c = canvas.getContext('2d');
      var cw = canvas.offsetWidth, ch = canvas.offsetHeight;
      if (!cw || !ch) { return; }
      var dpr = window.devicePixelRatio || 1;
      /* 高清绘制：canvas 像素 = CSS 尺寸 × dpr */
      if (canvas.width !== Math.round(cw * dpr) || canvas.height !== Math.round(ch * dpr)) {
        canvas.width = Math.round(cw * dpr);
        canvas.height = Math.round(ch * dpr);
      }
      var w = canvas.width, h = canvas.height;
      c.clearRect(0, 0, w, h);

      var bw = Math.max(2, Math.round(2.6 * dpr));
      var gap = Math.max(2, Math.round(2.2 * dpr));
      var bars = Math.max(8, Math.floor(w / (bw + gap)));
      if (visSmooth.length !== bars) {
        visSmooth = [];
        for (var si = 0; si < bars; si++) { visSmooth[si] = 0; }
      }
      /* 渐变：底部主题色半透明 → 上部主题色 → 顶部白，与 MD3 主色联动 */
      var prim = getComputedStyle(document.documentElement).getPropertyValue('--md-sys-color-primary').trim() || '#6750a4';
      var grad = c.createLinearGradient(0, h, 0, 0);
      grad.addColorStop(0, prim + '59');
      grad.addColorStop(0.55, prim + 'cc');
      grad.addColorStop(1, '#ffffff');
      c.fillStyle = grad;

      for (var i = 0; i < bars; i++) {
        var target;
        if (active) {
          var vi = Math.floor((i / bars) * data.length * 0.72 + 1);
          target = (data[vi] || 0) / 255;
        } else {
          /* 启动/缓冲期：轻缓模拟律动，视觉不空白等待 */
          visBoot += 0.025;
          target = 0.16 + 0.12 * Math.sin(visBoot + i * 0.55);
        }
        var prev = visSmooth[i] || 0;
        visSmooth[i] = prev + (target - prev) * 0.38;
        var bh = Math.max(2.4 * dpr, visSmooth[i] * (h - 3 * dpr));
        var x = i * (bw + gap);
        var y = h - bh;
        var r = Math.min(bw / 2, 2.4 * dpr);
        if (c.roundRect) {
          c.beginPath();
          c.roundRect(x, y, bw, bh, r);
          c.fill();
        } else {
          c.fillRect(x, y, bw, bh);
        }
      }
    };
    draw();
  }
  function stopVis() {
    if (rafId) { cancelAnimationFrame(rafId); rafId = null; }
    var canvas = q('.player-vis');
    if (canvas) {
      canvas.classList.remove('is-on');
      var c = canvas.getContext && canvas.getContext('2d');
      if (c) { c.clearRect(0, 0, canvas.width, canvas.height); }
    }
    /* 移除降级 CSS 音柱，确保不播放时不显示 */
    var vc = q('.vis-css');
    if (vc) { vc.remove(); }
  }

  /* ---------- 音量：滑块弹出（与搜索按钮同材质玻璃面板） ---------- */
  function syncVolUI() {
    var btn = q('.player-vol');
    if (btn) {
      var i = btn.querySelector('i');
      if (i) {
        i.className = (muted || vol === 0) ? 'ri-volume-mute-line' : (vol < 0.5 ? 'ri-volume-down-line' : 'ri-volume-up-line');
      }
    }
    var slider = q('.player-vol-slider');
    if (slider) {
      slider.value = String(Math.round((muted ? 0 : vol) * 100));
    }
    var num = q('.player-vol-num');
    if (num) { num.textContent = Math.round((muted ? 0 : vol) * 100); }
    var dslider = q('.dock-vol-slider');
    if (dslider) { dslider.value = String(Math.round((muted ? 0 : vol) * 100)); }
    var dnum = q('.dock-vol-num');
    if (dnum) { dnum.textContent = Math.round((muted ? 0 : vol) * 100); }
  }
  function toggleVolPop(force) {
    var pop = q('.player-vol-pop');
    if (!pop) { return; }
    var open = typeof force === 'boolean' ? force : pop.hidden;
    var btn = q('.player-vol');
    if (open) {
      pop.hidden = false;
      syncVolUI();
      if (btn) { btn.classList.add('is-pop-open'); }
      requestAnimationFrame(function () { pop.classList.add('is-open'); });
    } else {
      pop.classList.remove('is-open');
      if (btn) { btn.classList.remove('is-pop-open'); }
      setTimeout(function () { pop.hidden = true; }, 320);
    }
  }

  /* ---------- 歌单：按钮旁玻璃面板弹出（同材质平滑展开） ---------- */
  function renderList() {
    var ul = q('.player-plist-items');
    if (!ul) { return; }
    ul.innerHTML = '';
    CFG.list.forEach(function (item, i) {
      var li = document.createElement('li');
      li.className = 'player-plist-item' + (i === idx ? ' is-active' : '');
      li.innerHTML =
        '<span class="pli-cover">' + (coverOf(item) ? '<img src="' + coverOf(item) + '" alt="">' : '<i class="ri-music-2-line"></i>') + '</span>' +
        '<span class="pli-title">' + (item.title || ('曲目 ' + (i + 1))) + '</span>' +
        '<span class="pli-play"><i class="' + (i === idx && playing ? 'ri-pause-line' : 'ri-play-line') + '"></i></span>';
      li.addEventListener('click', function () {
        if (i === idx && audio && !audio.paused) { togglePlay(); return; }
        playAt(i);
        closeList();
      });
      ul.appendChild(li);
    });
  }
  function openList() {
    var pop = q('.player-plist-pop');
    if (!pop) { return; }
    renderList();
    var btn = q('.player-plist');
    if (btn) { btn.classList.add('is-pop-open'); }
    pop.hidden = false;
    requestAnimationFrame(function () { pop.classList.add('is-open'); });
  }
  function closeList() {
    var pop = q('.player-plist-pop');
    if (!pop) { return; }
    pop.classList.remove('is-open');
    var btn = q('.player-plist');
    if (btn) { btn.classList.remove('is-pop-open'); }
    setTimeout(function () { pop.hidden = true; }, 360);
  }
  function closePops() {
    closeList();
    toggleVolPop(false);
    closeDockList();
    toggleDockVol(false);
    /* 歌词浮层是常驻显示组件：只由歌词按钮开关，不随页面点击被动关闭 */
  }

  /* ---------- 歌词：左下角滚动歌词（参考 InspirX：当前行居中滚动 + 高亮层级 + localStorage 记忆开关） ---------- */
  var lyricLines = [];
  if (CFG.lyric) {
    String(CFG.lyric).split(/\r\n|\r|\n/).forEach(function (ln) {
      ln = ln.replace(/^\s+|\s+$/g, '');
      if (ln !== '') { lyricLines.push(ln); }
    });
  }
  var lyricTimer = null;
  var lyricPage = 0;
  var lrcVisible = true;
  var plfItems = [];
  var lastLrcIdx = -1;
  var PLF_ROW = 20;   /* 行高（与 CSS 同步） */
  var PLF_VIEW = 60;  /* 可视区高度 3 行（与 CSS 同步） */
  /* 歌词开关：完全由后台「歌词默认显示」设置决定（勾选=默认显示，不勾选=默认隐藏）。
     按钮点击在当前页面即时切换（Pjax 内保持）；刷新/重开回到后台设置状态 */
  function lrcPref() {
    return !!CFG.lyricDefault;
  }
  /* LRC 解析：[mm:ss.xx] 歌词 → [{t, text}] 按时间排序 */
  function parseLrc(lrc) {
    var out = [];
    if (!lrc) { return out; }
    var re = /\[(\d{1,2}):(\d{1,2})(?:[.:](\d{1,3}))?\]/g;
    String(lrc).split(/\r\n|\r|\n/).forEach(function (line) {
      var times = [];
      var rest = line.replace(re, function (_, mm, ss, ms) {
        times.push(parseInt(mm, 10) * 60 + parseInt(ss, 10) + parseInt(ms || '0', 10) / 1000);
        return '';
      });
      rest = rest.replace(/^\s+|\s+$/g, '');
      if (rest === '') { return; }
      times.forEach(function (t) { out.push({ t: t, text: rest }); });
    });
    out.sort(function (a, b) { return a.t - b.t; });
    return out;
  }
  /* LRC 纯文本行（无时间戳，用于未播放时轮播） */
  function lrcTextLines(lrc) {
    var lines = [];
    if (!lrc) { return lines; }
    String(lrc).split(/\r\n|\r|\n/).forEach(function (line) {
      var t = line.replace(/\[\d{1,2}:\d{1,2}(?:[.:]\d{1,3})?\]/g, '').replace(/^\s+|\s+$/g, '');
      if (t !== '') { lines.push(t); }
    });
    return lines;
  }
  /* 渲染滚动歌词列表 */
  function renderLrcList(texts) {
    var list = q('.plf-list');
    if (!list) { return; }
    list.innerHTML = '';
    plfItems = [];
    lastLrcIdx = -1;
    (texts || []).forEach(function (t) {
      var li = document.createElement('div');
      li.className = 'plf-item';
      li.textContent = t;
      list.appendChild(li);
      plfItems.push(li);
    });
    list.style.transform = 'translateY(0px)';
  }
  /* 滚动到第 i 行：当前行居中，首尾贴边，设置高亮 */
  function scrollLrc(i) {
    var list = q('.plf-list');
    var n = plfItems.length;
    if (!list || !n) { return; }
    i = Math.max(0, Math.min(n - 1, i));
    if (i === lastLrcIdx) { return; }
    lastLrcIdx = i;
    var y = (PLF_VIEW - PLF_ROW) / 2 - i * PLF_ROW;
    y = Math.max(PLF_VIEW - n * PLF_ROW - 6, Math.min(6, y));
    list.style.transform = 'translateY(' + y + 'px)';
    for (var k = 0; k < n; k++) { plfItems[k].classList.toggle('on', k === i); }
  }
  /* LRC 时间同步：定位当前行并滚动 */
  function syncLrc() {
    if (!lrcData || !lrcData.length) { return; }
    var ct = audio ? audio.currentTime : 0;
    var i = 0;
    while (i < lrcData.length - 1 && lrcData[i + 1].t <= ct) { i++; }
    scrollLrc(i);
  }
  /* 无 LRC：文本行滚动轮播 */
  function lyricStep() {
    if (!lyricLines.length) { return; }
    lyricPage++;
    scrollLrc(lyricPage % lyricLines.length);
  }
  /* 歌词模式切换：有 LRC 渲染时间行，无 LRC 渲染文本行轮播 */
  function ensureLyricMode() {
    var box = q('.player-lyric-float');
    if (!box) { return; }
    if (lrcData && lrcData.length) {
      clearInterval(lyricTimer);
      lyricTimer = null;
      renderLrcList(lrcData.map(function (x) { return x.text; }));
      lastLrcIdx = -1;
      syncLrc();
    } else if (lyricLines.length) {
      renderLrcList(lyricLines);
      lyricPage = 0;
      scrollLrc(0);
      if (!lyricTimer && !box.hidden) { lyricTimer = setInterval(lyricStep, 4000); }
    } else {
      renderLrcList(['暂无歌词']);
    }
  }
  /* 应用显示状态（不写存储） */
  function applyLrcVisible(v) {
    var box = q('.player-lyric-float');
    var btn = q('.player-lyric');
    /* 不播放音乐时也不显示歌词（播放后才按开关/后台设置显示） */
    var show = v && playing;
    if (box) {
      box.hidden = !show;
      if (show) {
        ensureLyricMode();
      } else {
        clearInterval(lyricTimer);
        lyricTimer = null;
      }
    }
    if (btn) { btn.classList.toggle('is-on', show); }
  }
  /* 显示/隐藏（后台设置决定默认态，按钮切换当前页面即时生效） */
  function setLrcVisible(v) {
    lrcVisible = v;
    applyLrcVisible(v);
  }
  function toggleLyricFloat(force) {
    var v = typeof force === 'boolean' ? force : !lrcVisible;
    setLrcVisible(v);
  }
  function closeLyric() {
    applyLrcVisible(false);
  }

  var sideHideTimer = null;
  function syncSideBtns() {
    var side = q('.player-side');
    if (!side) { return; }
    if (playing) {
      clearTimeout(sideHideTimer);
      side.classList.add('is-on');
    } else {
      /* 延迟隐藏：切歌/短暂暂停期间不闪烁 */
      clearTimeout(sideHideTimer);
      sideHideTimer = setTimeout(function () { side.classList.remove('is-on'); }, 300);
    }
  }
  /* ---------- UI 同步 ---------- */
  function syncUI() {
    var root = q('.tri-player-avatar');
    if (root) { root.classList.toggle('is-playing', playing); }
    syncSideBtns();
    var tg = q('.player-toggle i');
    if (tg) { tg.className = playing ? 'ri-pause-fill' : 'ri-play-fill'; }
    /* 名字/简介随播放切换 */
    applyIdentity();
    /* 列表内高亮 */
    var items = document.querySelectorAll('.player-plist-item');
    Array.prototype.forEach.call(items, function (li, i) {
      li.classList.toggle('is-active', i === idx);
      var pi = li.querySelector('.pli-play i');
      if (pi) { pi.className = (i === idx && playing) ? 'ri-pause-line' : 'ri-play-line'; }
    });
    syncDock();
    applyLrcVisible(lrcVisible);
  }

  /* ========== 悬浮播放器（头像滚出视口 → 页面底部居中弹出） ========== */
  var dockObserver = null;
  function syncDockProgress() {
    var bar = q('.dock-progress-bar');
    if (bar && audio && audio.duration && isFinite(audio.duration)) {
      bar.style.width = ((audio.currentTime / audio.duration) * 100) + '%';
    }
  }
  function syncDock() {
    var dock = q('.player-dock');
    if (!dock) { return; }
    var img = dock.querySelector('.dock-cover-img');
    var av = q('.tri-player-avatar img');
    if (img) {
      if (av) { img.src = av.src; }
      else {
        var curIt = current();
        img.src = curIt.pic_api || curIt.pic || coverOf(curIt) || savedAvatarSrc || '';
      }
    }
    var it = current();
    var ti = dock.querySelector('.dock-title');
    var ar = dock.querySelector('.dock-artist');
    if (ti) { ti.textContent = it.title || ('曲目 ' + (idx + 1)); }
    if (ar) { ar.textContent = it.artist || ''; }
    var pi = dock.querySelector('.dock-play i');
    if (pi) { pi.className = playing ? 'ri-pause-fill' : 'ri-play-fill'; }
    syncDockProgress();
    renderDockList();
  }
  function renderDockList() {
    var ul = q('.dock-plist-items');
    if (!ul) { return; }
    ul.innerHTML = '';
    CFG.list.forEach(function (item, i) {
      var li = document.createElement('li');
      li.className = 'dock-plist-item' + (i === idx ? ' is-active' : '');
      li.innerHTML =
        '<span class="pli-cover">' + (coverOf(item) ? '<img src="' + coverOf(item) + '" alt="">' : '<i class="ri-music-2-line"></i>') + '</span>' +
        '<span class="pli-title">' + (item.title || ('曲目 ' + (i + 1))) + '</span>' +
        '<span class="pli-play"><i class="' + (i === idx && playing ? 'ri-pause-line' : 'ri-play-line') + '"></i></span>';
      li.addEventListener('click', function (ev) {
        ev.preventDefault(); ev.stopPropagation();
        if (i === idx && audio && !audio.paused) { togglePlay(); return; }
        playAt(i);
        closeDockList();
      });
      ul.appendChild(li);
    });
  }
  function openDockList() {
    var pop = q('.dock-plist-pop');
    if (!pop) { return; }
    var open = !pop.classList.contains('is-open');
    if (open) { renderDockList(); pop.classList.add('is-open'); }
    else { pop.classList.remove('is-open'); }
  }
  function closeDockList() {
    var pop = q('.dock-plist-pop');
    if (pop) { pop.classList.remove('is-open'); }
  }
  function toggleDockVol(force) {
    var pop = q('.dock-vol-pop');
    if (!pop) { return; }
    var open = typeof force === 'boolean' ? force : !pop.classList.contains('is-open');
    if (open) {
      pop.classList.add('is-open');
      syncVolUI();
    } else {
      pop.classList.remove('is-open');
    }
  }
  function seekDock(clientX) {
    var wrap = q('.dock-progress');
    if (!wrap || !audio || !audio.duration) { return; }
    var r = wrap.getBoundingClientRect();
    var ratio = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    audio.currentTime = ratio * audio.duration;
    syncDockProgress();
  }
  function bindDock() {
    var dock = q('.player-dock');
    if (!dock) { return; }
    var map = {
      'dock-prev': function () { prev(); },
      'dock-next': function () { next(); },
      'dock-play': function () { togglePlay(); },
      'dock-cover': function () { togglePlay(); },
      'dock-vol': function () { toggleDockVol(); closeDockList(); },
      'dock-plist': function () { openDockList(); toggleDockVol(false); },
      'dock-lyric': function () { toggleLyricFloat(); }
    };
    Object.keys(map).forEach(function (cls) {
      var b = dock.querySelector('.' + cls);
      if (!b || b.__dockBound) { return; }
      b.__dockBound = true;
      b.addEventListener('click', function (ev) {
        ev.preventDefault();
        ev.stopPropagation();
        map[cls]();
      });
    });
  }
  function refreshDock() {
    if (typeof dockObserver === 'function') { dockObserver(); }
  }

  /* 悬浮音乐按钮：加入 FAB 按钮组，日夜切换下面 */
    function ensureDockToggleBtn() {
    var stack = q('.tri3-fab-stack');
    if (!stack) return;
    if (q('#dock-toggle-fab')) return;
    var btn = document.createElement('button');
    btn.className = 'fab-btn';
    btn.id = 'dock-toggle-fab';
    btn.setAttribute('aria-label', '音乐播放器');
    btn.innerHTML = '<i class="ri-music-2-line"></i>';
    btn.style.display = 'none';
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      var d = q('.player-dock');
      if (d && d.classList.contains('is-on')) {
        window._hideDock();
        window._dockAutoHidden = true;
      } else {
        window._showDockPersistent();
      }
    });
    /* 插入到日夜切换按钮后面 */
    var themeBtn = q('#theme-toggle-fab');
    if (themeBtn && themeBtn.nextSibling) {
      stack.insertBefore(btn, themeBtn.nextSibling);
    } else if (themeBtn) {
      stack.appendChild(btn);
    } else {
      stack.insertBefore(btn, stack.firstChild);
    }
    /* 按钮显示逻辑：dock 已经出现过、当前不在显示、头像不可见时才显示 */
    setInterval(function () {
      var av = q('.tri-player-avatar');
      var show = false;
      if (playing) {
        if (!av) {
          show = true;
        } else {
          var r = av.getBoundingClientRect();
          var avVisible = !(r.bottom <= 0 || r.top >= window.innerHeight);
          show = !avVisible;
        }
      }
      btn.style.display = show ? 'flex' : 'none';
    }, 300);
  }

  function initDockObserver() {
    var dock = q('.player-dock');
    if (!dock) { return; }
    bindDock();
    ensureDockToggleBtn();
    /* 进度条/可视化动态定位：left 跟随头像外框右缘（PC/移动端统一，不写死 160px）。
       头像外框 .tri-player-avatar 半入 banner 底部分界线，右缘 = 进度条起点；
       可视化在进度条起点右移 4px，紧贴进度条上方。 */
    var updateProgPos = function () {
      var av = q('.tri-player-avatar');
      var banner = q('.hero-slider');
      if (!av || !banner) { return; }
      var bRect = banner.getBoundingClientRect();
      var aRect = av.getBoundingClientRect();
      var right = Math.round(aRect.right - bRect.left);
      if (right < 0) { right = 0; }
      var prog = q('.player-progress');
      var vis = q('.player-vis');
      if (prog) { prog.style.left = right + 'px'; }
      if (vis) { vis.style.left = (right + 4) + 'px'; }
    };

    var dockAutoHideTimer = null;
    window._dockAutoHidden = false;
    window._showDock = function() {
      var d = q('.player-dock');
      if (!d) return;
      window.__dockShownOnce = true;
      window._dockAutoHidden = false;
      d.hidden = false;
      d.classList.add('is-on');
      clearTimeout(dockAutoHideTimer);
      dockAutoHideTimer = setTimeout(function () {
        d.classList.remove('is-on');
        window._dockAutoHidden = true;
      }, 10000);
      var lyr = q('.player-lyric-float');
      if (lyr) { lyr.classList.add('is-above-dock'); }
    }
    window._showDockPersistent = function() {
      var d = q('.player-dock');
      if (!d) return;
      window.__dockShownOnce = true;
      window._dockAutoHidden = false;
      d.hidden = false;
      d.classList.add('is-on');
      clearTimeout(dockAutoHideTimer);
      var lyr = q('.player-lyric-float');
      if (lyr) { lyr.classList.add('is-above-dock'); }
    }
    window._hideDock = function() {
      var d = q('.player-dock');
      if (!d) return;
      d.classList.remove('is-on');
      clearTimeout(dockAutoHideTimer);
      var lyr = q('.player-lyric-float');
      if (lyr) { lyr.classList.remove('is-above-dock'); }
    }
    var onScroll = function () {
      var d = q('.player-dock');
      var t = q('.tri-player-avatar');
      var vh = window.innerHeight;
      if (!d) { return; }
      var visible = false;
      if (t) {
        var r = t.getBoundingClientRect();
        visible = !(r.bottom <= 0 || r.top >= vh);
      }
      if (visible) {
        window._hideDock();
        window._dockAutoHidden = false;
        window.__dockShownOnce = false;
        closeDockList();
        toggleDockVol(false);
      } else if (playing && !window._dockAutoHidden) {
        if (!d.classList.contains('is-on')) {
          window._showDock();
        }
      }
    };
    dockObserver = onScroll;
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', function () { updateProgPos(); onScroll(); });
    /* Pjax 回首页 / 首页列表刷新后：元素被替换，重新计算进度条/可视化位置 */
    document.addEventListener('tri3:pjax', function () {
      if (q('.player-progress')) { updateProgPos(); }
    });
    document.addEventListener('tri3:homelist', function () {
      if (q('.player-progress')) { updateProgPos(); }
    });
    updateProgPos();
    onScroll();
    syncDock();
  }

  /* ---------- Meting API：拉取歌单（本地代理懒加载 / 外部 API 直连兼容） ---------- */
  function metingApiBase() {
    return String((CFG.meting && CFG.meting.api) || '').replace(/\/+$/, '');
  }
  /* 统一列表应用：meting 数据 → CFG.list（供主页歌单 / 外部卡片歌单共用） */
  function applyMetingData(data, srv) {
    var api = metingApiBase();
    if (!Array.isArray(data) || !data.length) { throw new Error('empty'); }
    srv = srv || CFG.meting.server || 'netease';
    CFG.list = data.map(function (d) {
      var sid = d.url_id || d.id || '';
      var isLocal = !!(d.url_id || d.pic_api);
      return {
        server: srv,
        title: d.name || d.title || '',
        artist: Array.isArray(d.artist) ? d.artist.join('/') : (d.artist || ''),
        url_id: sid,
        src: d.url || '',
        lrc: isLocal
          ? (d.lrc || (api + '?server=' + encodeURIComponent(srv) + '&type=lrc&id=' + encodeURIComponent(sid)))
          : (d.lrc || d.lyric || ''),
        pic_api: d.pic_api || '',
        pic: d.pic || '',
        lrcText: ''
      };
    }).filter(function (it) { return it.src !== '' || it.url_id !== ''; });
    if (!CFG.list.length) { throw new Error('no item'); }
    /* 默认歌词：首曲 LRC 纯文本行轮播（懒加载时先尝试拉取） */
    var firstLrc = CFG.list[0].lrc;
    if (typeof firstLrc === 'string' && /^https?:\/\//.test(firstLrc)) {
      fetch(firstLrc).then(function (r) { return r.text(); }).then(function (t) {
        var lines = lrcTextLines(t);
        if (lines.length) { lyricLines = lines; }
        ensureLyricMode();
      }).catch(function () {});
    } else {
      var fl = lrcTextLines(firstLrc);
      if (fl.length) { lyricLines = fl; }
      ensureLyricMode();
    }
    return CFG.list;
  }
  function fetchMeting() {
    if (!CFG.meting || !CFG.meting.api || !CFG.meting.id) {
      toast('未配置 Meting API 或资源 ID');
      return;
    }
    var api = metingApiBase();
    var srv = CFG.meting.server || 'netease';
      var url = api + '?server=' + encodeURIComponent(srv) +
              '&type=' + encodeURIComponent(CFG.meting.type || 'playlist') +
              '&id=' + encodeURIComponent(CFG.meting.id);
    fetch(url)
      .then(function (res) {
        if (!res.ok) { throw new Error('http ' + res.status); }
        return res.json();
      })
      .then(function (data) {
        applyMetingData(data, CFG.meting.server || 'netease');
      })
      .catch(function () {
        toast('Meting 拉取失败，请检查 API 地址/资源 ID');
      });
  }

  /* ---------- 事件绑定（委托，Pjax 后由 Tri3Init 重绑状态） ---------- */
  document.addEventListener('click', function (e) {
    var t = e.target;
    if (!t || !t.closest) { return; }
    var hp = t.closest('.player-hover-play');
    if (hp) { e.preventDefault(); e.stopPropagation(); togglePlay(); return; }
    var pc = t.closest('.player-controls');
    if (pc) {
      e.preventDefault(); e.stopPropagation();
      if (t.closest('.player-prev')) { prev(); }
      else if (t.closest('.player-next')) { next(); }
      else if (t.closest('.player-toggle')) { togglePlay(); }
      return;
    }
    if (t.closest('.player-vol')) { e.preventDefault(); e.stopPropagation(); toggleVolPop(); closeList(); return; }
    if (t.closest('.player-plist')) { e.preventDefault(); e.stopPropagation(); openList(); toggleVolPop(false); return; }
    if (t.closest('.player-lyric')) { e.preventDefault(); e.stopPropagation(); toggleLyricFloat(); return; }
    /* 悬浮播放器 dock */
    var dc = t.closest('.player-dock');
    if (dc) {
      e.preventDefault(); e.stopPropagation();
      if (t.closest('.dock-prev')) { prev(); }
      else if (t.closest('.dock-next')) { next(); }
      else if (t.closest('.dock-play')) { togglePlay(); }
      else if (t.closest('.dock-cover')) { togglePlay(); }
      else if (t.closest('.dock-vol')) { toggleDockVol(); closeDockList(); }
      else if (t.closest('.dock-plist')) { openDockList(); toggleDockVol(false); }
      else if (t.closest('.dock-lyric')) { toggleLyricFloat(); }
      return;
    }
    /* 点击播放器区域外：收起弹出面板 */
    if (!t.closest('.player-side') && !t.closest('.player-controls') && !t.closest('.player-dock')) {
      closePops();
    }
  });

  /* 音量滑块拖动 */
  document.addEventListener('input', function (e) {
    if (e.target && e.target.classList &&
        (e.target.classList.contains('player-vol-slider') || e.target.classList.contains('dock-vol-slider'))) {
      var v = parseInt(e.target.value, 10) / 100;
      if (isNaN(v)) { return; }
      vol = v;
      muted = false;
      if (audio) { audio.volume = v; audio.muted = false; }
      syncVolUI();
    }
  });

  document.addEventListener('click', function (e) {
    var bar = e.target && e.target.closest ? e.target.closest('.player-progress') : null;
    if (bar) { seekTo(e.clientX); }
    var dbar = e.target && e.target.closest ? e.target.closest('.dock-progress') : null;
    if (dbar) { seekDock(e.clientX); }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { closePops(); }
  });

  /* 空间键播放/暂停（避免与输入框冲突） */
  document.addEventListener('keydown', function (e) {
    var tag = (e.target && e.target.tagName) || '';
    if (e.key === ' ' && tag !== 'INPUT' && tag !== 'TEXTAREA' && !e.target.isContentEditable) {
      togglePlay();
      e.preventDefault();
    }
  });

  window.TriPlayer = {
    playAt: playAt,
    toggle: togglePlay,
    prev: prev,
    next: next,
    state: function () { return { playing: playing, idx: idx }; },
    listCount: function () { return CFG.list.length; },getAudio: function(){return audio;},getCurrentTime: function(){return audio?audio.currentTime:0;},getDuration: function(){return audio?audio.duration:0;},
    /* 外部单曲播放（说说音乐卡片联动）：替换列表后播放第 0 首 */
    playSong: function (item) {
      if (!CFG.enabled || !item) { return; }
      CFG.list = [item];
      idx = 0;
      playAt(0);
    },
    /* 外部歌单播放（文章/说说歌单卡片联动）：直接传入已解析的歌曲数组，start 指定起始曲目，server 指定平台 */
    playList: function (items, start, server) {
      if (!CFG.enabled || !items || !items.length) { return; }
      var api = metingApiBase();
      var srv = server || 'netease';
      CFG.list = items.map(function (d) {
        var sid = d.url_id || d.id || '';
        return {
          server: srv,
          title: d.name || d.title || '',
          artist: Array.isArray(d.artist) ? d.artist.join('/') : (d.artist || ''),
          url_id: sid,
          src: d.url || '',
          lrc: (d.lrc && String(d.lrc).indexOf('http') === 0)
            ? d.lrc
            : (api + '?server=' + encodeURIComponent(srv) + '&type=lrc&id=' + encodeURIComponent(sid)),
          pic_api: d.pic_api || d.pic || '',
          pic: d.pic || '',
          lrcText: ''
        };
      }).filter(function (it) { return it.src !== '' || it.url_id !== ''; });
      if (!CFG.list.length) { return; }
      idx = (typeof start === 'number' && start > 0 && start < CFG.list.length) ? start : 0;
      playAt(idx);
    },
    /* 外部 Meting 拉取播放（歌单卡片联动）：按 平台+类型+ID 拉取后直接播放 */
    playMeting: function (server, type, id) {
      if (!CFG.enabled || !id) { return; }
      var api = metingApiBase();
      if (!api) { toast('未配置 Meting API'); return; }
      fetch(api + '?server=' + encodeURIComponent(server || 'netease') +
            '&type=' + encodeURIComponent(type || 'playlist') +
            '&id=' + encodeURIComponent(id))
        .then(function (res) {
          if (!res.ok) { throw new Error('http ' + res.status); }
          return res.json();
        })
        .then(function (data) {
          try {
            applyMetingData(data, server || 'netease');
            idx = 0;
            playAt(0);
          } catch (e) {
            toast('歌单拉取失败');
          }
        })
        .catch(function () { toast('歌单拉取失败，请检查平台与 ID'); });
    }
  };

  /* 初始化：保存博主头像（暂停时恢复），Meting 异步拉取或自定义歌单 */
  saveAvatar();
  initDockObserver();
  lrcVisible = lrcPref();
  applyLrcVisible(lrcVisible);
  if (!window._triPlayerAutoInit && CFG.source === 'meting' && CFG.meting && CFG.meting.id) {
    window._triPlayerAutoInit = true;
    fetchMeting();
  } else if (CFG.list && CFG.list.length) {
    ensureLyricMode();
  }

  /* Pjax / 初始化后恢复 UI（幂等，不重置歌词开关） */
  window.TriPlayerSync = function () {
    if (!CFG.enabled) { return; }
    savedName = null;
    savedBio = null;
    saveAvatar(); /* 先保存新 DOM 的博主头像，再覆盖歌曲封面，暂停恢复才正确 */
    if (playing) {
      var prog = q('.player-progress');
      if (prog) { prog.classList.add('is-on'); }
      applyIdentity(); /* 名字/简介 -> 歌名/歌手 */
      switchCover();   /* 封面 -> 歌曲封面（Pjax 重建 DOM 后恢复） */
      startVis();
    }
    syncUI();
    applyLrcVisible(lrcVisible);
    initDockObserver();
  };
})();
